document.addEventListener("DOMContentLoaded", function () {
    const models = ["RandomForest", "LinearRegression", "LogisticRegression", "LSTM"];
    const evaluationContainer = document.getElementById("evaluation-results");

    // Fetch logs and evaluation results for each model
    models.forEach((model) => {
        fetch(`/evaluate-model?model=${model}`)
            .then((response) => response.json())
            .then((data) => {
                displayModelLogs(model, data);
                displayPlots(model);
            })
            .catch((error) => console.error(`Error fetching evaluation data for ${model}:`, error));
    });

    function displayModelLogs(modelName, logs) {
        const modelLogsSection = document.createElement("div");
        modelLogsSection.classList.add("model-logs");
        modelLogsSection.innerHTML = `<h3>${modelName} Evaluation</h3>`;

        // Append logs (e.g., MSE, Classification Report)
        if (logs.mse) {
            modelLogsSection.innerHTML += `<p><strong>MSE:</strong> ${logs.mse}</p>`;
        }
        if (logs.classification_report) {
            const report = logs.classification_report;
            const reportHTML = `<pre>${JSON.stringify(report, null, 2)}</pre>`;
            modelLogsSection.innerHTML += `<p><strong>Classification Report:</strong></p>${reportHTML}`;
        }

        evaluationContainer.appendChild(modelLogsSection);
    }

    function displayPlots(modelName) {
        const plotContainer = document.createElement("div");
        plotContainer.classList.add("model-plots");

        // Append Confusion Matrix plot
        const confusionMatrix = document.createElement("img");
        confusionMatrix.src = `/static/${modelName}_confusion_matrix.png`;
        confusionMatrix.alt = `${modelName} Confusion Matrix`;
        plotContainer.appendChild(confusionMatrix);

        // Append ROC Curve plot if applicable
        if (["RandomForest", "LogisticRegression", "LSTM"].includes(modelName)) {
            const rocCurve = document.createElement("img");
            rocCurve.src = `/static/${modelName}_roc_curve.png`;
            rocCurve.alt = `${modelName} ROC Curve`;
            plotContainer.appendChild(rocCurve);
        }

        // Append Loss plot for LSTM
        if (modelName === "LSTM") {
            const lossPlot = document.createElement("img");
            lossPlot.src = `/static/LSTM_loss.png`;
            lossPlot.alt = "LSTM Loss Plot";
            plotContainer.appendChild(lossPlot);
        }

        evaluationContainer.appendChild(plotContainer);
    }
});
